67	/**
68	 * @author Vitaliy Fedoriv
69	 */
70	
71	@RestController
72	@CrossOrigin(exposedHeaders = "errors, content-type")
73	@RequestMapping("/api")
74	public class OwnerRestControllerV1 implements OwnersApi {
75	
76	    /** Dedicated audit logger; emits one line per successful owner create. */
77	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
78	
79	    private final ClinicService clinicService;
80	
81	    private final OwnerMapper ownerMapper;
82	
83	    private final PetMapper petMapper;
84	
85	    private final VisitMapper visitMapper;
86	
87	    /** HTTP header carrying the caller-supplied idempotency key for owner creates. */
88	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
89	
90	    /**
91	     * Records the owner created for each previously-seen idempotency key, so a create that repeats a
92	     * key returns the originally created owner instead of creating a duplicate. Keyed by the raw
93	     * header value; the stored value is the response returned for the first successful create.
94	     */
95	    private final Map<String, OwnerDto> idempotentCreations = new ConcurrentHashMap<>();
96	
97	    public OwnerRestControllerV1(ClinicService clinicService,
98	                                 OwnerMapper ownerMapper,
99	                                 PetMapper petMapper,
100	                                 VisitMapper visitMapper) {
101	        this.clinicService = clinicService;
102	        this.ownerMapper = ownerMapper;
103	        this.petMapper = petMapper;
104	        this.visitMapper = visitMapper;
105	    }
106	
107	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
108	    @Override
109	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
110	        Collection<Owner> owners;
111	        if (lastName != null) {
112	            owners = this.clinicService.findOwnerByLastName(lastName);
113	        } else {
114	            owners = this.clinicService.findAllOwners();
115	        }
116	        if (owners.isEmpty()) {
117	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
118	        }
119	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
120	    }
121	
122	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
123	    @Override
124	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
125	        Owner owner = this.clinicService.findOwnerById(ownerId);
126	        if (owner == null) {
127	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
128	        }
129	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
130	    }
131	
132	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
133	    @Override
134	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
135	        // Idempotent create: when the request carries an 'Idempotency-Key' header that we have already
136	        // seen, return the owner originally created for that key with 200 instead of creating a
137	        // duplicate (which would otherwise be rejected as a 409 conflict). A brand-new key is recorded
138	        // below once the create succeeds; a request without the header is never treated as idempotent.
139	        String idempotencyKey = currentIdempotencyKey();
140	        if (idempotencyKey != null) {
141	            OwnerDto existing = idempotentCreations.get(idempotencyKey);
142	            if (existing != null) {
143	                return new ResponseEntity<>(existing, HttpStatus.OK);
144	            }
145	        }
146	        // Normalize the address up front so every downstream use (the required-field check,
147	        // household-duplicate detection, the shared household id and the stored/returned value)
148	        // works from the same canonical form. The structured 'addressLine1'/'addressLine2' fields are
149	        // preferred when present; the flat 'address' remains accepted for backward compatibility. Each
150	        // supplied line is normalized the same way, and the composed address is the normalized
151	        // addressLine1 with a single space and the normalized addressLine2 appended when present.
152	        String normalizedAddressLine1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
153	        String normalizedAddressLine2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
154	        boolean structuredAddress = !isBlank(normalizedAddressLine1);
155	        String normalizedAddress;
156	        if (structuredAddress) {
157	            normalizedAddress = normalizedAddressLine2.isEmpty()
158	                ? normalizedAddressLine1
159	                : normalizedAddressLine1 + " " + normalizedAddressLine2;
160	        } else {
161	            normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
162	        }
163	        List<String> missingFields = new ArrayList<>();
164	        if (isBlank(ownerFieldsDto.getFirstName())) {
165	            missingFields.add("firstName");
166	        }
167	        if (isBlank(ownerFieldsDto.getLastName())) {
168	            missingFields.add("lastName");
169	        }
170	        // Reject an address that is blank once normalized (e.g. whitespace-only input).
171	        if (isBlank(normalizedAddress)) {
172	            missingFields.add("address");
173	        }
174	        if (isBlank(ownerFieldsDto.getCity())) {
175	            missingFields.add("city");
176	        }
177	        if (isBlank(ownerFieldsDto.getTelephone())) {
178	            missingFields.add("telephone");
179	        }
180	        if (!missingFields.isEmpty()) {
181	            throw new InvalidOwnerFieldsException(missingFields);
182	        }
183	        // A supplied registration date may not lie in the future: reject with 400 when the caller
184	        // provides a date later than the server's current date. Checked against the raw supplied value
185	        // (before any business-day adjustment) so a future date is never silently accepted.
186	        if (ownerFieldsDto.getRegistrationDate() != null
187	            && ownerFieldsDto.getRegistrationDate().isAfter(LocalDate.now())) {
188	            throw new FutureRegistrationDateException(ownerFieldsDto.getRegistrationDate());
189	        }
190	        // Determine the effective registration date up front so every downstream use (the daily
191	        // create-limit, the stored value and anything derived from it such as the membership number's
192	        // year segment) works from the same business-day-adjusted date. The effective date is the
193	        // supplied value when present, otherwise the server's current date; a weekend date is rolled
194	        // forward to the following Monday.
195	        LocalDate effectiveRegistrationDate = ownerFieldsDto.getRegistrationDate() != null
196	            ? ownerFieldsDto.getRegistrationDate()
197	            : LocalDate.now();
198	        effectiveRegistrationDate = toBusinessDay(effectiveRegistrationDate);
199	        // Reject the request once the day's owner-creation limit is reached: when 100 or more owners
200	        // already carry this adjusted business day's registration date, no further owners may be
201	        // created for that day.
202	        int ownersRegisteredToday = countOwnersRegisteredOn(effectiveRegistrationDate);
203	        if (ownersRegisteredToday >= MAX_OWNERS_PER_DAY) {
204	            throw new DailyOwnerLimitExceededException(effectiveRegistrationDate);
205	        }
206	        // Flag a bulk signup once more than 80 owners have already been created for this
207	        // business day, sharing the same daily accumulation path as the create-limit rule above.
208	        boolean bulkSignupWarning = ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD;
209	        // Reject the request when the owner's city is already full: a city that already holds the
210	        // maximum of 50 owners (compared case-insensitively, as elsewhere) accepts no more.
211	        if (countOwnersInCity(ownerFieldsDto.getCity()) >= MAX_OWNERS_PER_CITY) {
212	            throw new CityAtCapacityException(ownerFieldsDto.getCity());
213	        }
214	        // Postcode is optional; when present it must be a 4-digit value that is valid for the
215	        // owner's city per the fixed region ranges. A malformed or out-of-range postcode is
216	        // rejected with a 400. An absent postcode leaves the request contract unchanged.
217	        validatePostcode(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode());
218	        // Normalize the telephone into E.164 form; a number that cannot form a valid
219	        // E.164 value is rejected with a 400.
220	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
221	        // Email is optional; when present it must be a syntactically valid address and is
222	        // stored lower-cased. An invalid address is rejected with a 400.
223	        String normalizedEmail = normalizeEmail(ownerFieldsDto.getEmail());
224	        // Derive the household id up front. It is a deterministic function of the normalized last name
225	        // and the postcode, so owners sharing a last name and postcode independently derive the same
226	        // value and are the same household. It is always computed (never null), regardless of whether
227	        // the caller opts into a shared household; 'sharesHousehold' now only bypasses the household
228	        // duplicate block below.
229	        String normalizedLastName = collapse(ownerFieldsDto.getLastName());
230	        String householdId = householdId(normalizedLastName, ownerFieldsDto.getPostcode());
231	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
232	        // All duplicate detection is consolidated into a single derived identity key:
233	        // 'normalizedTelephone + | + (email or empty) + | + householdId'. Because the telephone is
234	        // part of the key, two members of the same household (same householdId) with different
235	        // telephones have different keys and are both allowed; only an exact whole-key match is a
236	        // duplicate. Reject with 409 when a new owner's whole identity key equals an existing one's.
237	        String identityKey = identityKey(normalizedTelephone, normalizedEmail, householdId);
238	        boolean identityInUse = this.clinicService.findAllOwners().stream()
239	            .filter(existing -> !existing.isDeleted())
240	            .anyMatch(existing -> identityKey.equals(
241	                identityKey(existing.getTelephone(), existing.getEmail(), existing.getHouseholdId())));
242	        if (identityInUse) {
243	            throw new DuplicateOwnerIdentityException(identityKey);
244	        }
245	        // Because the household is keyed on (last name, postcode), any existing owner carrying this
246	        // computed household id is already a member of this household. A second such owner is rejected
247	        // as a household duplicate (409) unless the caller declares 'sharesHousehold', which bypasses
248	        // the block and admits the owner as a declared household member.
249	        boolean householdMemberExists = this.clinicService.findAllOwners().stream()
250	            .filter(existing -> !existing.isDeleted())
251	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
252	        if (householdMemberExists && !sharesHousehold) {
253	            throw new DuplicateOwnerHouseholdException(ownerFieldsDto.getLastName(), normalizedAddress);
254	        }
255	        HttpHeaders headers = new HttpHeaders();
256	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
257	        // Store the composed, normalized address plus the normalized structured lines. The structured
258	        // lines are only retained when the owner was supplied in the structured form; a flat-address
259	        // owner keeps them null.
260	        owner.setAddress(normalizedAddress);
261	        owner.setAddressLine1(structuredAddress ? normalizedAddressLine1 : null);
262	        owner.setAddressLine2(structuredAddress && !normalizedAddressLine2.isEmpty()
263	            ? normalizedAddressLine2 : null);
264	        owner.setTelephone(normalizedTelephone);
265	        owner.setEmail(normalizedEmail);
266	        owner.setHouseholdId(householdId);
267	        // Record how many existing owners (before this create) share this owner's first and last
268	        // name, compared case-insensitively. Computed against the current owners so the new owner
269	        // itself is never counted.
270	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
271	        // Record the size of this owner's household (owners sharing the same householdId) after this
272	        // create: the existing members already stamped with the shared identifier plus this new
273	        // owner. An owner not admitted into any household is a household of one.
274	        owner.setHouseholdSize(countHouseholdMembers(householdId) + 1);
275	        // Persist the bulk-signup flag computed above so it is returned on subsequent reads.
276	        owner.setBulkSignupWarning(bulkSignupWarning);
277	        // Store the business-day-adjusted effective registration date computed above. This defaults
278	        // to the server's current date when none was supplied and rolls any weekend date forward to
279	        // the following Monday, so everything derived from it (e.g. the membership number's year
280	        // segment) uses the adjusted date.
281	        owner.setRegistrationDate(effectiveRegistrationDate);
282	        // Assign the customer code: '<REGION>-<HASH8>' where REGION is the region derived from the
283	        // owner's postcode (falling back to the city-to-region table, else 'UNKNOWN', matching the
284	        // locality derivation) and HASH8 is the first 8 upper-case hex characters of
285	        // SHA-256(normalizedTelephone + lastName). Sequence numbers are no longer used.
286	        // Compute the base code, then de-duplicate it: if the computed value collides with an
287	        // existing owner's customerCode, append '-<n>' using the smallest n of 2 or more that
288	        // yields a value no existing owner already carries.
289	        owner.setCustomerCode(deduplicateCustomerCode(customerCode(
290	            deriveRegion(owner.getPostcode(), owner.getCity()), normalizedTelephone, owner.getLastName())));
291	        // Soft-match detection: an owner that cleared the hard-duplicate checks above may still
292	        // resemble an existing owner when it shares that owner's last name and postcode but carries a
293	        // different telephone. A declared household member ('sharesHousehold') is never a suspected
294	        // duplicate, so it is exempt; any other owner reaching here shares no household with an
295	        // existing owner (a household match without 'sharesHousehold' was already rejected above).
296	        // Flag a matched owner as a possible duplicate, recording its id; otherwise the flag is false
297	        // with no matched id.
298	        Owner possibleDuplicateOwner = sharesHousehold ? null : findPossibleDuplicate(
299	            owner.getLastName(), owner.getPostcode(), normalizedTelephone);
300	        owner.setPossibleDuplicate(possibleDuplicateOwner != null);
301	        owner.setPossibleDuplicateOf(possibleDuplicateOwner == null ? null : possibleDuplicateOwner.getId());
302	        this.clinicService.saveOwner(owner);
303	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
304	        // Emit an audit trail line for the successful create, carrying the owner id, the assigned
305	        // customer code, the effective registration date, the numeric membership level and the
306	        // assigned membership number.
307	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
308	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), ownerDto.getMembershipLevel(),
309	            ownerDto.getMembershipNumber());
310	        headers.setLocation(UriComponentsBuilder.newInstance()
311	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
312	        // Remember the created owner against its idempotency key (when one was supplied) so a later
313	        // create repeating the same key returns this same owner rather than creating a duplicate.
314	        if (idempotencyKey != null) {
315	            idempotentCreations.put(idempotencyKey, ownerDto);
316	        }
317	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
318	    }
319	
320	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
321	    @Override
322	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
323	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
324	        if (currentOwner == null) {
325	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
326	        }
327	        currentOwner.setAddress(ownerFieldsDto.getAddress());
328	        currentOwner.setCity(ownerFieldsDto.getCity());
329	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
330	        currentOwner.setLastName(ownerFieldsDto.getLastName());
331	        currentOwner.setTelephone(toE164(ownerFieldsDto.getTelephone()));
332	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
333	        this.clinicService.saveOwner(currentOwner);
334	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
335	    }
336	
337	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
338	    @Transactional
339	    @Override
340	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
341	        Owner owner = this.clinicService.findOwnerById(ownerId);
342	        if (owner == null) {
343	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
344	        }
345	        // Soft delete: flag the owner deleted and retain the row rather than removing it, so the
346	        // owner is still readable via GET afterwards (now carrying 'deleted' true) while the create
347	        // endpoint's duplicate/identity checks below skip it.
348	        owner.setDeleted(true);
349	        this.clinicService.saveOwner(owner);
350	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
351	    }
352	
353	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
354	    @Override
355	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
356	        Owner owner = this.clinicService.findOwnerById(ownerId);
357	        if (owner == null) {
358	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
359	        }
360	        HttpHeaders headers = new HttpHeaders();
361	        Pet pet = petMapper.toPet(petFieldsDto);
362	        owner.setId(ownerId);
363	        pet.setOwner(owner);
364	        pet.getType().setName(null);
365	        this.clinicService.savePet(pet);
366	        PetDto petDto = petMapper.toPetDto(pet);
367	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
368	            .buildAndExpand(pet.getId()).toUri());
369	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
370	    }
371	
372	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
373	    @Override
374	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
375	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
376	        if (currentOwner != null) {
377	            Pet currentPet = this.clinicService.findPetById(petId);
378	            if (currentPet != null) {
379	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
380	                currentPet.setName(petFieldsDto.getName());
381	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
382	                this.clinicService.savePet(currentPet);
383	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
384	            }
385	        }
386	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
387	    }
388	
389	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
390	    @Override
391	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
392	        HttpHeaders headers = new HttpHeaders();
393	        Visit visit = visitMapper.toVisit(visitFieldsDto);
394	        Pet pet = new Pet();
395	        pet.setId(petId);
396	        visit.setPet(pet);
397	        this.clinicService.saveVisit(visit);
398	        VisitDto visitDto = visitMapper.toVisitDto(visit);
399	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
400	            .buildAndExpand(visit.getId()).toUri());
401	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
402	    }
403	
404	
405	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
406	    @Override
407	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
408	        Owner owner = this.clinicService.findOwnerById(ownerId);
409	        if (owner != null) {
410	            Pet pet = owner.getPet(petId);
411	            if (pet != null) {
412	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
413	            }
414	        }
415	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
416	    }
417	
418	    /**
419	     * Read the {@code Idempotency-Key} header from the current request, or {@code null} when the
420	     * header is absent, blank, or no request is bound to the thread. The header is not part of the
421	     * generated API signature, so it is read from the ambient request rather than a method parameter.
422	     */
423	    private static String currentIdempotencyKey() {
424	        RequestAttributes attributes = RequestContextHolder.getRequestAttributes();
425	        if (!(attributes instanceof ServletRequestAttributes servletAttributes)) {
426	            return null;
427	        }
428	        String key = servletAttributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
429	        return isBlank(key) ? null : key;
430	    }
431	
432	    private static boolean isBlank(String value) {
433	        return value == null || value.trim().isEmpty();
434	    }
435	
436	    /**
437	     * Normalize an owner identity field for household-duplicate comparison: trim, collapse every
438	     * run of whitespace to a single space, and lower-case. Used so that last name and address are
439	     * compared case-insensitively with collapsed whitespace.
440	     */
441	    private static String collapse(String value) {
442	        if (value == null) {
443	            return "";
444	        }
445	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
446	    }
447	
448	    /**
449	     * Common street-type abbreviations expanded during address normalization.
450	     */
451	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
452	        "ST", "STREET",
453	        "RD", "ROAD",
454	        "AVE", "AVENUE");
455	
456	    /**
457	     * Normalize an owner address into its canonical stored/compared form: trim, collapse every run
458	     * of whitespace to a single space, upper-case, and expand common street-type abbreviations
459	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). Returns an empty string for
460	     * a {@code null} or blank input. The transformation is idempotent, so an already-normalized
461	     * address maps to itself.
462	     */
463	    private static String normalizeAddress(String value) {
464	        if (value == null) {
465	            return "";
466	        }
467	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase();
468	        if (collapsed.isEmpty()) {
469	            return "";
470	        }
471	        String[] tokens = collapsed.split(" ");
472	        StringBuilder sb = new StringBuilder(collapsed.length());
473	        for (int i = 0; i < tokens.length; i++) {
474	            if (i > 0) {
475	                sb.append(' ');
476	            }
477	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
478	        }
479	        return sb.toString();
480	    }
481	
482	    /**
483	     * Derive the stable household identifier shared by owners with the same normalized last name
484	     * and postcode. It is a deterministic function of those two values, so every member of a
485	     * household independently derives the same identifier: the first 12 upper-case hex characters
486	     * of {@code SHA-256(normalizedLastName + '|' + postcode)}. A {@code null} postcode contributes
487	     * an empty segment.
488	     */
489	    private static String householdId(String normalizedLastName, String postcode) {
490	        try {
491	            byte[] digest = MessageDigest.getInstance("SHA-256")
492	                .digest((normalizedLastName + "|" + (postcode == null ? "" : postcode))
493	                    .getBytes(StandardCharsets.UTF_8));
494	            StringBuilder sb = new StringBuilder(digest.length * 2);
495	            for (byte b : digest) {
496	                sb.append(String.format("%02x", b));
497	            }
498	            return sb.substring(0, 12).toUpperCase();
499	        }
500	        catch (NoSuchAlgorithmException e) {
501	            throw new IllegalStateException("SHA-256 not available", e);
502	        }
503	    }
504	
505	    /**
506	     * Derive the identity key into which all duplicate detection is consolidated:
507	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}. A null email or
508	     * household id contributes an empty segment. Two owners are duplicates only when their whole
509	     * identity keys are equal.
510	     */
511	    private static String identityKey(String telephone, String email, String householdId) {
512	        return (telephone == null ? "" : telephone)
513	            + "|" + (email == null ? "" : email)
514	            + "|" + (householdId == null ? "" : householdId);
515	    }
516	
517	    /**
518	     * Count the existing owners that share the given first and last name, compared
519	     * case-insensitively. Called before the new owner is saved, so the returned value reflects the
520	     * namesakes that already existed at creation time (the new owner itself is not included).
521	     */
522	    private int countNamesakes(String firstName, String lastName) {
523	        return (int) this.clinicService.findAllOwners().stream()
524	            .filter(existing -> existing.getFirstName() != null && existing.getLastName() != null)
525	            .filter(existing -> existing.getFirstName().equalsIgnoreCase(firstName)
526	                && existing.getLastName().equalsIgnoreCase(lastName))
527	            .count();
528	    }
529	
530	    /**
531	     * Count the existing owners that already belong to the given household (i.e. carry the same
532	     * non-null householdId). Called after any existing members have been backfilled with the shared
533	     * identifier but before the new owner is saved, so the returned value reflects the members that
534	     * already existed at creation time (the new owner itself is not included). Returns 0 when the
535	     * new owner is not part of any household ({@code householdId} is null).
536	     */
537	    private int countHouseholdMembers(String householdId) {
538	        if (householdId == null) {
539	            return 0;
540	        }
541	        return (int) this.clinicService.findAllOwners().stream()
542	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
543	            .count();
544	    }
545	
546	    /**
547	     * Find an existing owner that this new owner is a possible (soft) duplicate of: one that shares
548	     * the new owner's last name (compared case-insensitively) and postcode while carrying a different
549	     * (already normalized) telephone. When several existing owners match, the earliest (lowest id) is
550	     * returned so the result is deterministic. Returns {@code null} when there is no such owner —
551	     * including when the new owner has no last name or postcode, since a shared postcode is required
552	     * to match.
553	     */
554	    private Owner findPossibleDuplicate(String lastName, String postcode, String normalizedTelephone) {
555	        if (isBlank(lastName) || isBlank(postcode)) {
556	            return null;
557	        }
558	        return this.clinicService.findAllOwners().stream()
559	            .filter(existing -> lastName.equalsIgnoreCase(existing.getLastName()))
560	            .filter(existing -> postcode.equals(existing.getPostcode()))
561	            .filter(existing -> !normalizedTelephone.equals(existing.getTelephone()))
562	            .min(java.util.Comparator.comparing(Owner::getId))
563	            .orElse(null);
564	    }
565	
566	    /**
567	     * The maximum number of owners a single city may contain. Once a city holds this many owners a
568	     * request to create another owner in it is rejected as a conflict.
569	     */
570	    private static final int MAX_OWNERS_PER_CITY = 50;
571	
572	    /**
573	     * Count the existing owners registered in the given city, compared case-insensitively (as in
574	     * {@link #nextCustomerCode}). Called before the new owner is saved, so the returned value
575	     * reflects the owners that already existed at creation time.
576	     */
577	    private int countOwnersInCity(String city) {
578	        return (int) this.clinicService.findAllOwners().stream()
579	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
580	            .count();
581	    }
582	
583	    /**
584	     * The maximum number of owners that may be created on a single day. Once this many owners
585	     * already carry a given day's registration date, a request to create another owner that day is
586	     * rejected with a 429.
587	     */
588	    private static final int MAX_OWNERS_PER_DAY = 100;
589	
590	    /**
591	     * The number of owners that may be created on a single day before the bulk-signup warning is
592	     * flagged. Once more than this many owners already carry a given day's registration date, a
593	     * newly created owner is flagged with {@code bulkSignupWarning} set true.
594	     */
595	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
596	
597	    /**
598	     * Count the existing owners whose registration date is the given day. Called before the new
599	     * owner is saved, so the returned value reflects the owners that already existed at creation
600	     * time.
601	     */
602	    private int countOwnersRegisteredOn(LocalDate date) {
603	        return (int) this.clinicService.findAllOwners().stream()
604	            .filter(existing -> date.equals(existing.getRegistrationDate()))
605	            .count();
606	    }
607	
608	    /** Fixed public holidays the business-day roll skips. */
609	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
610	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
611	        LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"), LocalDate.parse("2026-12-28"));
612	
613	    /**
614	     * Roll a date forward onto a business day: Saturdays, Sundays and listed public holidays are
615	     * advanced one day at a time until a non-weekend, non-holiday day is reached, while an ordinary
616	     * business day is returned unchanged. Used so the effective registration date (whether supplied
617	     * or defaulted) always falls on a business day.
618	     */
619	    private static LocalDate toBusinessDay(LocalDate date) {
620	        while (isWeekendOrHoliday(date)) {
621	            date = date.plusDays(1);
622	        }
623	        return date;
624	    }
625	
626	    private static boolean isWeekendOrHoliday(LocalDate date) {
627	        return switch (date.getDayOfWeek()) {
628	            case SATURDAY, SUNDAY -> true;
629	            default -> PUBLIC_HOLIDAYS.contains(date);
630	        };
631	    }
632	
633	    /**
634	     * Build the customer code for a new owner: {@code '<REGION>-<HASH8>'} where REGION is the region
635	     * derived from the owner's postcode/city and HASH8 is the first 8 upper-case hex characters of
636	     * {@code SHA-256(normalizedTelephone + lastName)} (e.g. {@code 'NSW-1A2B3C4D'}).
637	     */
638	    private static String customerCode(String region, String normalizedTelephone, String lastName) {
639	        return region + "-" + hash8(normalizedTelephone + (lastName == null ? "" : lastName));
640	    }
641	
642	    /**
643	     * Ensure the computed customer code is unique across existing owners. When {@code base} is
644	     * already free it is returned unchanged; otherwise {@code '-<n>'} is appended using the smallest
645	     * {@code n} of 2 or more that produces a value no existing owner already carries.
646	     */
647	    private String deduplicateCustomerCode(String base) {
648	        java.util.Set<String> inUse = this.clinicService.findAllOwners().stream()
649	            .map(Owner::getCustomerCode)
650	            .filter(java.util.Objects::nonNull)
651	            .collect(java.util.stream.Collectors.toSet());
652	        if (!inUse.contains(base)) {
653	            return base;
654	        }
655	        int n = 2;
656	        while (inUse.contains(base + "-" + n)) {
657	            n++;
658	        }
659	        return base + "-" + n;
660	    }
661	
662	    /**
663	     * First 8 upper-case hex characters of {@code SHA-256(input)}.
664	     */
665	    private static String hash8(String input) {
666	        try {
667	            byte[] digest = MessageDigest.getInstance("SHA-256")
668	                .digest(input.getBytes(StandardCharsets.UTF_8));
669	            StringBuilder sb = new StringBuilder(digest.length * 2);
670	            for (byte b : digest) {
671	                sb.append(String.format("%02x", b));
672	            }
673	            return sb.substring(0, 8).toUpperCase();
674	        }
675	        catch (NoSuchAlgorithmException e) {
676	            throw new IllegalStateException("SHA-256 not available", e);
677	        }
678	    }
679	
680	    /**
681	     * Derive the owner's region, preferring the postcode: look up the region by postcode range first
682	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), then fall back to the city-to-region table
683	     * (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD) when the postcode is absent or in no known
684	     * range. Returns {@code 'UNKNOWN'} when neither source resolves a region. This mirrors the
685	     * mapper's locality derivation, so the customer code's region segment and the owner's locality
686	     * always agree.
687	     */
688	    private static String deriveRegion(String postcode, String city) {
689	        if (postcode != null && postcode.matches("\\d{4}")) {
690	            int value = Integer.parseInt(postcode);
691	            for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
692	                int[] range = entry.getValue();
693	                if (value >= range[0] && value <= range[1]) {
694	                    return entry.getKey();
695	                }
696	            }
697	        }
698	        if (city == null) {
699	            return "UNKNOWN";
700	        }
701	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
702	    }
703	
704	    /**
705	     * The fixed city-to-region table used to validate a supplied postcode against the owner's city
706	     * (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD). A city not present here has no known region
707	     * and accepts any 4-digit postcode.
708	     */
709	    private static final Map<String, String> CITY_REGION = Map.of(
710	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
711	
712	    /**
713	     * The fixed region-to-postcode ranges (inclusive): NSW 2000-2099, VIC 3000-3099, QLD 4000-4099.
714	     * Each entry is a two-element {@code {low, high}} array.
715	     */
716	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
717	        "NSW", new int[] {2000, 2099},
718	        "VIC", new int[] {3000, 3099},
719	        "QLD", new int[] {4000, 4099});
720	
721	    /**
722	     * Validate an optional owner postcode. Does nothing when no postcode was supplied (the field is
723	     * optional and the request contract stays backward-compatible). When supplied it must be exactly
724	     * 4 digits and, if the city maps to a known region, must fall within that region's inclusive
725	     * range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any
726	     * 4-digit postcode. A malformed or out-of-range postcode throws an
727	     * {@link InvalidOwnerFieldsException} so the request is rejected with a 400.
728	     */
729	    private static void validatePostcode(String city, String postcode) {
730	        if (postcode == null || postcode.isEmpty()) {
731	            return;
732	        }
733	        if (!postcode.matches("\\d{4}")) {
734	            throw new InvalidOwnerFieldsException(List.of("postcode"));
735	        }
736	        String region = city == null ? null : CITY_REGION.get(city);
737	        if (region == null) {
738	            return;
739	        }
740	        int[] range = REGION_POSTCODES.get(region);
741	        int value = Integer.parseInt(postcode);
742	        if (value < range[0] || value > range[1]) {
743	            throw new InvalidOwnerFieldsException(List.of("postcode"));
744	        }
745	    }
746	
747	    /**
748	     * Required national-number length for each E.164 country calling code we validate: a
749	     * {@code '+61'} (Australia) number carries 9 national digits and a {@code '+1'} (NANP) number
750	     * carries 10. Country codes not listed here are accepted at any (generally valid) length.
751	     */
752	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
753	        "1", 10,
754	        "61", 9);
755	
756	    /**
757	     * Convert a raw telephone into E.164 form. Spaces, dashes and brackets are stripped. A leading
758	     * {@code '+'} with its country code is preserved; otherwise the Australian country code
759	     * {@code '+61'} is assumed and a single leading {@code '0'} is dropped from the national digits.
760	     * The result must be a {@code '+'} followed by 8 to 15 digits, and for a recognised country code
761	     * its national-number length must match ({@code '+61'} requires 9 national digits, {@code '+1'}
762	     * requires 10); otherwise an {@link InvalidOwnerFieldsException} is thrown so the request is
763	     * rejected with a 400.
764	     */
765	    private static String toE164(String raw) {
766	        String cleaned = raw.trim().replaceAll("[\\s()\\-]", "");
767	        boolean hasCountryCode = cleaned.startsWith("+");
768	        String digits = hasCountryCode ? cleaned.substring(1) : cleaned;
769	        if (!digits.matches("\\d+")) {
770	            throw new InvalidOwnerFieldsException(List.of("telephone"));
771	        }
772	        if (!hasCountryCode) {
773	            if (digits.startsWith("0")) {
774	                digits = digits.substring(1);
775	            }
776	            digits = "61" + digits;
777	        }
778	        if (digits.length() < 8 || digits.length() > 15) {
779	            throw new InvalidOwnerFieldsException(List.of("telephone"));
780	        }
781	        // For a recognised country code, the national number (the digits after the code) must be
782	        // exactly the expected length for that country. Match the longest known code so a shorter
783	        // code that is a prefix of another cannot mask it.
784	        for (int codeLength = 3; codeLength >= 1; codeLength--) {
785	            if (digits.length() <= codeLength) {
786	                continue;
787	            }
788	            String countryCode = digits.substring(0, codeLength);
789	            Integer requiredNationalLength = NATIONAL_NUMBER_LENGTHS.get(countryCode);
790	            if (requiredNationalLength != null) {
791	                if (digits.length() - codeLength != requiredNationalLength) {
792	                    throw new InvalidOwnerFieldsException(List.of("telephone"));
793	                }
794	                break;
795	            }
796	        }
797	        return "+" + digits;
798	    }
799	
800	    /**
801	     * Pragmatic syntactic check for an email address: a non-empty local part, an {@code @},
802	     * and a domain with at least one dot-separated label, none of which contain whitespace or
803	     * a second {@code @}. This is deliberately permissive but rejects obviously malformed input.
804	     */
805	    private static final Pattern EMAIL_PATTERN =
806	        Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
807	
808	    /**
809	     * Disposable email domains that are not accepted for an owner. An email whose domain (the part
810	     * after the {@code @}, compared case-insensitively) is on this blocklist is rejected with a 400.
811	     */
812	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
813	        "mailinator.com", "tempmail.com", "guerrillamail.com");
814	
815	    /**
816	     * Validate and normalize an optional owner email. Returns {@code null} when no email was
817	     * supplied (the field is optional). When supplied it must be a syntactically valid address whose
818	     * domain is not on the disposable-domain blocklist, otherwise an
819	     * {@link InvalidOwnerFieldsException} is thrown so the request is rejected with a 400. A valid
820	     * address is returned lower-cased.
821	     */
822	    private static String normalizeEmail(String email) {
823	        if (email == null || email.isEmpty()) {
824	            return null;
825	        }
826	        String trimmed = email.trim();
827	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
828	            throw new InvalidOwnerFieldsException(List.of("email"));
829	        }
830	        String normalized = trimmed.toLowerCase();
831	        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
832	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
833	            throw new InvalidOwnerFieldsException(List.of("email"));
834	        }
835	        return normalized;
836	    }
837	}
